INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('3', '3', 'ar', 'تأسست بموجب المرسوم الرئاسي رقم PP-22، وتمثل القوة الأكاديمية الموحدة للمؤسسات التقنية في بخارى. حائزة على الاستقلالية الأكاديمية والمالية الكاملة منذ عام 2026، لنصنع مستقبلاً رقمياً ومستداماً لأوزبكستان وآسيا الوسطى.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('4', '4', 'ar', 'تواصل', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('5', '5', 'ar', 'استكشف حياة الحرم الجامعي', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('6', '6', 'ar', 'ملف حالة جامعة بخارى', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
