INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('9', '9', 'ar', 'مرشح لتصنيف QS العالمي', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('10', '10', 'ar', 'مرشح نشط مدرج في السجل العالمي الرسمي لجامعات QS الأعلى تصنيفاً.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
