INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('12', '12', 'ar', 'الوريث الشرعي لأول كلية تقنية مسائية تأسست في بخارى عام 1959.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('13', '13', 'ar', 'الاندماج المؤسسي', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('14', '14', 'ar', 'هويتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('15', '15', 'ar', 'تشكلت من خلال دمج معهد بخارى للهندسة والتكنولوجيا ومعهد بخارى لإدارة الموارد الطبيعية (القرار الرئاسي رقم PP-22)، لتجمع الجامعة تحت سقفها نخبة العلماء والباحثين والمرافق التعليمية في المنطقة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('16', '16', 'ar', 'تهدف جامعتنا إلى أن تكون قاعدة تكنولوجية كبرى في أوزبكستان، وتزويد الطلاب بالخبرات الهندسية العميقة، والقدرات البحثية، والاندماج الصناعي بالتعاون المباشر مع شركات كبرى مثل أوزبك نفتغاز.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('17', '17', 'ar', 'الأهداف الاستراتيجية', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('18', '18', 'ar', 'الرسالة والرؤية', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('19', '19', 'ar', 'رسالتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('20', '20', 'ar', 'تقديم تعليم تقني متميز، وقيادة البحوث العلمية الرائدة، وتخريج نخبة من المهندسين القادرين على إدخال التقنيات الخضراء المتقدمة، وحلول الكيمياء البترولية، والبنية التحتية الرقمية في القطاعات الوطنية.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('21', '21', 'ar', 'رؤيتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('22', '22', 'ar', 'تأمين مكانة بارزة ضمن أفضل 1,000 جامعة عالمية في تصنيف QS بحلول عام 2030، وتأسيس الجامعة كمركز بحثي رئيسي في آسيا الوسطى للرقمنة الصناعية وإدارة الموارد الموفرة للطاقة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('23', '23', 'ar', 'الأخلاقيات التشغيلية', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
