INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('26', '26', 'ar', 'الالتزام بالأخلاقيات الدولية، والشفافية في نظام درجات ECTS المعتمد، ومكافحة الفساد عبر أنظمة المراقبة والامتثال لدينا.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
