INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('28', '28', 'ar', 'رعاية مواهب ومشاريع الطلاب الناشئة، ودعم التقنيات الوطنية الحائزة على براءات اختراع، وابتكار حلول هندسية رقمية.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
