INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('30', '30', 'ar', 'دعم الطلاب الدوليين، وتفعيل برامج الشهادات المزدوجة، وتقديم برامج تدريب شاملة للشباب ذوي الاحتياجات الخاصة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00');
