INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('137', '137', 'ar', 'تعليم تطبيقي في أنظمة المياه وإدارة الأراضي والبيئة والهيدروجيولوجيا وهندسة النقل والمرونة البيئية.', '2026-08-04 19:55:06', '2026-08-04 19:55:06');
