INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('140', '140', 'ar', 'كلمة رئيسة الجامعة', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('141', '141', 'ar', 'تحويل التعليم التقني لمواكبة العصر العالمي الجديد', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('142', '142', 'ar', 'مرحباً بكم في جامعة بخارى الحكومية التقنية. تدخل جامعتنا عام 2026 باستقلال أكاديمي ومالي كامل، مما يتيح لنا بناء مناهج ECTS حديثة متوافقة مع أرقى المعايير التقنية الأوروبية. ومن خلال دمج المعاهد الفنية، أسسنا مركزاً علمياً جباراً.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('143', '143', 'ar', 'نحن نؤمن بأن الهندسة الحقيقية لا يمكن تعليمها في معزل عن الواقع. ولهذا يتعاون طلابنا بشكل وثيق مع الشركات الوطنية، ويجرون بحوثاً في الكيمياء البترولية الحاصلة على براءات اختراع، ويشاركون في شهادات مزدوجة مع لاتفيا وبيلاروسيا وتركيا.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('144', '144', 'ar', 'سيرة وإنجازات رئيسة الجامعة', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('145', '145', 'ar', 'توعية خاصة', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('146', '146', 'ar', 'بيان توعوي خاص من رئيسة الجامعة: لحماية شبابنا', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('147', '147', 'ar', 'في عالمنا المعاصر، تحاصر المخاطر والآفات عقول شبابنا دون قيود، وأخطرها الإدمان والجرائم المتعلقة به. هذه الآفة تسلب الإنسان تدريجياً صحته وعقله وأهدافه وأحلامه.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('148', '148', 'ar', 'إلى أبنائنا الطلاب', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('149', '149', 'ar', 'كل منكم يمثل القوة المجهزة للتطوير العلمي والتقني والاقتصادي لبلدنا. الانضباط واليقظة والتفكير المستقل هي ركائز نجاحكم. مرحلة الدراسة الجامعية هي الأثمن؛ املؤوها بالمعرفة والبحث والأهداف السامية، وابتعدوا عن الفضول المؤذي ومغريات السوء. وكونوا أوفياء لمهنتكم وأحلامكم.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('150', '150', 'ar', 'إلى أولياء الأمور الكرام', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('151', '151', 'ar', 'متابعة الحالة النفسية لأبنائنا، وأنشطتهم خارج الدراسة، وأصدقائهم، تمثل الدرع الواقي لحمايتهم. كلمة نصح واحدة ودقيقة حوار صادقة قد تقي من الوقوع في أخطاء جسيمة. ابقوا على تواصل مع رحلتهم الأكاديمية.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('152', '152', 'ar', 'إلى الأساتذة الأفاضل', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('153', '153', 'ar', 'إن علمكم وخبرتكم هما الحجر الأساس لبناء فكر الشباب. إن الوقاية من الإدمان ليست مجرد قيود، بل هي قوة أخلاقية ومسؤولية جماعية ووعي مجتمعي. لنعمل معاً يداً بيد لتعزيز البيئة الصحية والنقية في جامعتنا، ولنكن مهتمين بكل طالب.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('154', '154', 'ar', 'سدوكات غافوروفنا صديقوفا', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('155', '155', 'ar', 'دكتوراه في الفلسفة (PhD) في العلوم التربوية', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
