INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('184', '184', 'ar', 'اعتباراً من 1 يناير 2026، منحت الجامعة استقلالية أكاديمية وتنظيمية ومالية كاملة لتطبيق أنظمة الساعات المعتمدة المستقلة وتسريع تصنيفها العالمي.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
