INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('203', '19', 'en', 'Our Mission', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('204', '20', 'en', 'To deliver premier technical education, drive pioneering scientific research, and produce elite engineering graduates who can introduce advanced green technologies, petrochemical synthesis solutions, and digital infrastructures in national sectors.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('205', '21', 'en', 'Our Vision', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('206', '22', 'en', 'To secure a prominent position among the top 1,000 global universities in the QS World Rankings by 2030, establishing BSTU as Central Asia\'s primary research hub for industrial digitalization and energy-efficient resource management.', '2026-07-22 11:45:01', '2026-07-22 11:45:01');
