INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('504', '137', 'ru', 'Прикладное образование в сфере водных систем, землеустройства, экологии, гидрогеологии, транспортной инженерии и экологической устойчивости.', '2026-08-04 19:55:06', '2026-08-04 19:55:06');
