INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('692', '141', 'uz', 'Global davr uchun texnik ta\'limni transformatsiya qilish', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('693', '142', 'uz', 'Buxoro davlat texnika universitetiga xush kelibsiz. Universitetimiz 2026-yilga to\'liq akademik va moliyaviy mustaqillik bilan qadam qo\'ydi, bu esa bizga Yevropa ta\'lim standartlariga mos keladigan zamonaviy ECTS kredit tizimini joriy etish imkonini beradi. Birlashgan ilmiy markaz sifatida biz ulkan imkoniyatlar yaratdik.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('694', '143', 'uz', 'Biz haqiqiy muhandislik amaliyotdan uzilgan holda o\'rganilmasligiga ishonamiz. Shuning uchun talabalarimiz yirik sanoat korxonalari bilan hamkorlik qiladilar va Latviya, Belarus, Turkiya kabi davlatlar bilan qo\'shma dasturlarda ishtirok etadilar. Biz global muammolarga tayyor mutaxassislarni tayyorlaymiz.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('695', '144', 'uz', 'Rektor faoliyati va yutuqlari bilan tanishish', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('696', '145', 'uz', 'Maxsus ogohlantirish', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('697', '146', 'uz', 'Rektorning yoshlar va jamoatchilikka murojaati', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('698', '147', 'uz', 'Bugungi kunda dunyoda yoshlar hayotiga ta\'sir qiluvchi zararli illatlar cheklovsiz kirib kelmoqda. Shular orasida eng xavflisi — giyohvandlik va u bilan bog\'liq jinoyatlardir. Bu illat insonni sog\'liq, ong va maqsadlardan sezdirmasdan uzoqlashtiradi.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('699', '148', 'uz', 'Talaba-yoshlarga', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('700', '149', 'uz', 'Sizlar mamlakatimiz ilmiy-texnik rivoji uchun tayyorlanayotgan kuchsizlar. Sizdan tartib-intizom, hushyorlik va mustaqil fikrlash talab etiladi. Talabalik davrini bilim va yuksak maqsadlar bilan to\'ldirish sizning qo\'lingizda. Vaqtinchalik qiziqishlarga berilmang. Tanlagan kasbingizga sodiq bo\'ling.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('701', '150', 'uz', 'Hurmatli ota-onalarga', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('702', '151', 'uz', 'Farzandlarimizning ruhiy holati va darsdan tashqari mashg\'ulotlarini kuzatib borish — xavfsizlik yo\'lidagi eng samarali choradir. Bir daqiqa samimiy suhbat ba\'zan katta xatolarning oldini oladi.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('703', '152', 'uz', 'Muhtaram ustozlarga', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('704', '153', 'uz', 'Sizning hayotiy tajribangiz yoshlar ongida mustahkam poydevor yaratadi. Giyohvandlikning oldini olish faqat cheklov emas, balki jamoaviy mas\'uliyatdir. Universitetimizda sog\'lom muhitni birgalikda mustahkamlaylik. Har bir talabaga e\'tiborli bo\'laylik.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('705', '154', 'uz', 'Sadoqat Gafforovna Siddiqova', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('706', '155', 'uz', 'Pedagogika fanlari bo\'yicha falsafa doktori (PhD)', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
