INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES ('709', '158', 'uz', '1959-yildagi kechki texnika fakultetidan mustaqil yetakchi davlat texnika universitetigacha bo\'lgan yo\'l.', '2026-07-22 11:45:04', '2026-07-22 11:45:04');
