INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('2', '1', 'uz', 'Parolingizni tiklash', 'Platform BSTU', 'Assalomu alaykum!', 'Hisobingiz uchun parolni tiklash so‘rovi olingani sababli ushbu xabar yuborildi.', 'Parolni tiklash', 'Ushbu parolni tiklash havolasi {minutes} daqiqadan so‘ng amal qilishni to‘xtatadi.', 'Agar parolni tiklashni so‘ramagan bo‘lsangiz, hech qanday amal talab qilinmaydi.', 'Hurmat bilan,', 'Platform BSTU', 'Agar \"{action_label}\" tugmasini bosishda muammo bo‘lsa, quyidagi URL manzilni brauzeringizga ko‘chirib joylashtiring:', '© {year} Platform BSTU. Barcha huquqlar himoyalangan.', '2026-08-04 12:49:38', '2026-08-04 12:49:38');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('3', '1', 'ru', 'Сброс пароля', 'Platform BSTU', 'Здравствуйте!', 'Вы получили это письмо, потому что мы получили запрос на сброс пароля для вашей учетной записи.', 'Сбросить пароль', 'Срок действия этой ссылки для сброса пароля истечет через {minutes} минут.', 'Если вы не запрашивали сброс пароля, дополнительных действий не требуется.', 'С уважением,', 'Platform BSTU', 'Если у вас не получается нажать кнопку \"{action_label}\", скопируйте и вставьте ссылку ниже в браузер:', '© {year} Platform BSTU. Все права защищены.', '2026-08-04 12:49:38', '2026-08-04 12:49:38');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('4', '1', 'ar', 'إعادة تعيين كلمة المرور', 'منصة BSTU', 'مرحبا!', 'تصلك هذه الرسالة لأننا تلقينا طلبا لإعادة تعيين كلمة المرور الخاصة بحسابك.', 'إعادة تعيين كلمة المرور', 'ستنتهي صلاحية رابط إعادة تعيين كلمة المرور خلال {minutes} دقيقة.', 'إذا لم تطلب إعادة تعيين كلمة المرور، فلا يلزم اتخاذ أي إجراء آخر.', 'مع التحية،', 'منصة BSTU', 'إذا واجهت مشكلة في الضغط على زر \"{action_label}\"، انسخ الرابط أدناه والصقه في متصفحك:', '© {year} منصة BSTU. جميع الحقوق محفوظة.', '2026-08-04 12:49:38', '2026-08-04 12:49:38');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('5', '2', 'en', 'Welcome to the BSTU newsletter', 'BSTU International', 'Thank you for subscribing', 'You are now subscribed to the BSTU International newsletter. We will send you selected university updates, academic news, event announcements, and international student opportunities.', 'Visit BSTU International', 'Your subscription email: {email}', 'You will receive only relevant updates from our official platform.', 'Warm regards,', 'BSTU International Team', 'You can visit the website using the link below.', '© {year} BSTU International. All rights reserved.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('6', '2', 'uz', 'BSTU yangiliklar byulleteniga xush kelibsiz', 'BSTU International', 'Obuna bo‘lganingiz uchun rahmat', 'Siz BSTU International yangiliklar byulleteniga obuna bo‘ldingiz. Endi universitet yangiliklari, akademik xabarlar, tadbir eʼlonlari va xalqaro talabalar uchun imkoniyatlar haqida xabarlar olasiz.', 'BSTU International saytiga o‘tish', 'Obuna email manzilingiz: {email}', 'Biz faqat rasmiy platformamizdagi muhim va dolzarb yangiliklarni yuboramiz.', 'Hurmat bilan,', 'BSTU International jamoasi', 'Saytga quyidagi havola orqali o‘tishingiz mumkin.', '© {year} BSTU International. Barcha huquqlar himoyalangan.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('7', '2', 'ru', 'Добро пожаловать в рассылку BSTU', 'BSTU International', 'Спасибо за подписку', 'Вы подписались на рассылку BSTU International. Мы будем отправлять вам отобранные новости университета, академические объявления, события и возможности для иностранных студентов.', 'Перейти на BSTU International', 'Email подписки: {email}', 'Вы будете получать только актуальные сообщения с нашей официальной платформы.', 'С уважением,', 'Команда BSTU International', 'Вы можете перейти на сайт по ссылке ниже.', '© {year} BSTU International. Все права защищены.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('8', '2', 'ar', 'مرحبا بك في النشرة الإخبارية لـ BSTU', 'BSTU International', 'شكرا لاشتراكك', 'تم اشتراكك الآن في النشرة الإخبارية لموقع BSTU International. سنرسل لك أحدث أخبار الجامعة، وإعلانات الفعاليات، والمستجدات الأكاديمية، وفرص الطلاب الدوليين.', 'زيارة موقع BSTU International', 'بريد الاشتراك: {email}', 'ستصلك فقط التحديثات المهمة من منصتنا الرسمية.', 'مع خالص التحية،', 'فريق BSTU International', 'يمكنك زيارة الموقع من خلال الرابط أدناه.', '© {year} BSTU International. جميع الحقوق محفوظة.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('9', '3', 'en', 'We received your inquiry', 'BSTU International', 'Your inquiry has been received', 'Hello {name}, thank you for contacting BSTU International. Your message about \"{subject}\" has been received and will be reviewed by our team.', 'Visit Contact Page', 'Please follow your email inbox for our reply.', 'We will contact you using this email address as soon as your inquiry is reviewed.', 'Kind regards,', 'BSTU International Support', 'You can return to the contact page using the link below.', '© {year} BSTU International. All rights reserved.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('10', '3', 'uz', 'Murojaatingiz qabul qilindi', 'BSTU International', 'Murojaatingiz qabul qilindi', 'Assalomu alaykum {name}, BSTU International bilan bog‘langaningiz uchun rahmat. \"{subject}\" mavzusidagi xabaringiz qabul qilindi va jamoamiz tomonidan ko‘rib chiqiladi.', 'Aloqa sahifasiga o‘tish', 'Javobimizni olish uchun email pochtangizni kuzatib boring.', 'Murojaatingiz ko‘rib chiqilgach, siz bilan shu email orqali bog‘lanamiz.', 'Hurmat bilan,', 'BSTU International qo‘llab-quvvatlash xizmati', 'Aloqa sahifasiga quyidagi havola orqali qaytishingiz mumkin.', '© {year} BSTU International. Barcha huquqlar himoyalangan.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('11', '3', 'ru', 'Ваш запрос получен', 'BSTU International', 'Ваш запрос принят', 'Здравствуйте, {name}. Спасибо за обращение в BSTU International. Ваше сообщение по теме «{subject}» получено и будет рассмотрено нашей командой.', 'Открыть страницу контактов', 'Пожалуйста, следите за почтой, чтобы получить наш ответ.', 'После рассмотрения запроса мы свяжемся с вами по этому email адресу.', 'С уважением,', 'Служба поддержки BSTU International', 'Вы можете вернуться на страницу контактов по ссылке ниже.', '© {year} BSTU International. Все права защищены.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
INSERT INTO `auth_email_template_translations` (`id`, `auth_email_template_id`, `locale`, `subject`, `brand_name`, `greeting`, `intro`, `action_label`, `expiry_notice`, `no_action_notice`, `salutation`, `signature`, `subcopy`, `footer`, `created_at`, `updated_at`) VALUES ('12', '3', 'ar', 'تم استلام استفسارك', 'BSTU International', 'تم استلام استفسارك بنجاح', 'مرحبا {name}، شكرا لتواصلك مع BSTU International. تم استلام رسالتك بخصوص \"{subject}\" وسيقوم فريقنا بمراجعتها.', 'زيارة صفحة التواصل', 'يرجى متابعة بريدك الإلكتروني لاستلام الرد.', 'سنتواصل معك عبر هذا البريد بعد مراجعة استفسارك.', 'مع خالص التحية،', 'فريق دعم BSTU International', 'يمكنك الرجوع إلى صفحة التواصل من خلال الرابط أدناه.', '© {year} BSTU International. جميع الحقوق محفوظة.', '2026-08-04 13:25:35', '2026-08-04 13:25:35');
