INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('17', '5', 'en', 'Academic Integrity', 'Upholding international ethics, transparency in ECTS grading, and zero tolerance for corruption through our Compliance Control systems.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 13:38:12');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('18', '5', 'uz', 'Akademik halollik', 'Xalqaro etika, ECTS baholashdagi shaffoflik va Komplayens nazorati tizimlari orqali korrupsiyaga mutlaq murosasizlikni taʼminlash.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('19', '5', 'ru', 'Академическая честность', 'Поддержка международной этики, прозрачности оценивания ECTS и нулевой терпимости к коррупции через системы комплаенс-контроля.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('20', '5', 'ar', 'النزاهة الأكاديمية', 'تعزيز الأخلاقيات الدولية والشفافية في تقييم ECTS وعدم التسامح مطلقًا مع الفساد من خلال أنظمة الرقابة والامتثال.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('21', '6', 'en', 'Innovation Leadership', 'Fostering student startup talent, supporting national patented technologies, and driving digital engineering solutions.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 13:38:12');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('22', '6', 'uz', 'Innovatsion yetakchilik', 'Talabalar startap salohiyatini rivojlantirish, milliy patentlangan texnologiyalarni qoʻllab-quvvatlash va raqamli muhandislik yechimlarini ilgari surish.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('23', '6', 'ru', 'Инновационное лидерство', 'Развитие студенческих стартапов, поддержка национальных запатентованных технологий и продвижение цифровых инженерных решений.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_item_translations` (`id`, `home_section_item_id`, `locale`, `title`, `description`, `label`, `action_label`, `created_at`, `updated_at`) VALUES ('24', '6', 'ar', 'ريادة الابتكار', 'تنمية مواهب الطلاب في الشركات الناشئة، ودعم التقنيات الوطنية الحاصلة على براءات اختراع، ودفع حلول الهندسة الرقمية.', NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
