INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('13', '4', 'en', 'Strategic Goals', 'Mission & Vision', 'Institutional Merge', 'Our university aims to become a major technological base in Uzbekistan, equipping students with deep engineering expertise, research capabilities, and global industrial integration, partnering directly with conglomerates like Uzbekneftegaz JSC.', 'Our Identity', NULL, 'Explore Campus Life', '/video-bdtu', 'Mission & Vision BSTU', '2026-08-03 13:38:12', '2026-08-03 16:24:32');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('14', '4', 'uz', 'Strategik maqsadlar', 'Missiya va qarash', 'Institutsional birlashuv', 'Universitetimiz Oʻzbekistonda yirik texnologik bazaga aylanishni, talabalarni chuqur muhandislik bilimlari, tadqiqot salohiyati va global sanoat integratsiyasi bilan taʼminlashni hamda Uzbekneftegaz AJ kabi yirik korxonalar bilan bevosita hamkorlik qilishni maqsad qiladi.', 'Bizning identitetimiz', NULL, 'Kampus hayotini ko‘rish', '/video-bdtu', 'BSTU missiyasi va qarashi', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('15', '4', 'ru', 'Стратегические цели', 'Миссия и видение', 'Институциональное объединение', 'Наш университет стремится стать крупной технологической базой Узбекистана, предоставляя студентам глубокие инженерные знания, исследовательские возможности и интеграцию с мировой промышленностью, сотрудничая напрямую с такими объединениями, как АО «Узбекнефтегаз».', 'Наша идентичность', NULL, 'Изучить жизнь кампуса', '/video-bdtu', 'Миссия и видение БГТУ', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('16', '4', 'ar', 'الأهداف الاستراتيجية', 'الرسالة والرؤية', 'الاندماج المؤسسي', 'تهدف جامعتنا إلى أن تصبح قاعدة تكنولوجية كبرى في أوزبكستان، من خلال تزويد الطلاب بخبرة هندسية عميقة وقدرات بحثية وتكامل صناعي عالمي، مع شراكات مباشرة مع مؤسسات كبرى مثل Uzbekneftegaz JSC.', 'هويتنا', NULL, 'استكشف حياة الحرم الجامعي', '/video-bdtu', 'رسالة ورؤية BSTU', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('17', '5', 'en', 'Operational Ethics', 'Core Values', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 13:38:12');
