INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('20', '5', 'ar', 'الأخلاقيات التشغيلية', 'القيم الأساسية', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-03 13:38:12', '2026-08-03 14:03:58');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('21', '6', 'en', 'Institutional Merge', 'Our Identity', NULL, 'Formed through the integration of the Bukhara Engineering-Technological Institute and the Bukhara Institute of Natural Resources Management (Presidential Resolution No. PP-22), BSTU brings together the region\'s elite scholars, researchers, and campus facilities.', NULL, 'Our university aims to become a major technological base in Uzbekistan, equipping students with deep engineering expertise, research capabilities, and global industrial integration, partnering directly with conglomerates like Uzbekneftegaz JSC.', 'About Us', '/about', 'Our university aims to become a major technological base in Uzbekistan', '2026-08-03 13:38:12', '2026-08-03 18:34:34');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('22', '6', 'uz', 'Institutsional birlashuv', 'Bizning identitetimiz', NULL, 'Buxoro muhandislik-texnologiya instituti va Buxoro tabiiy resurslarni boshqarish instituti integratsiyasi asosida tashkil etilgan BSTU (Prezident qarori No. PP-22) hududning yetakchi olimlari, tadqiqotchilari va kampus imkoniyatlarini birlashtiradi.', NULL, 'Universitetimiz Oʻzbekistonda yirik texnologik bazaga aylanishni, talabalarni chuqur muhandislik bilimlari, tadqiqot salohiyati va global sanoat integratsiyasi bilan taʼminlashni hamda Uzbekneftegaz AJ kabi yirik korxonalar bilan bevosita hamkorlik qilishni maqsad qiladi.', 'Biz haqimizda', '/about', 'Universitetimiz O‘zbekistonda yirik texnologik bazaga aylanishni maqsad qilgan', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('23', '6', 'ru', 'Институциональное объединение', 'Наша идентичность', NULL, 'Созданный путем интеграции Бухарского инженерно-технологического института и Бухарского института управления природными ресурсами (Постановление Президента No. PP-22), БГТУ объединяет ведущих ученых, исследователей и инфраструктуру кампусов региона.', NULL, 'Наш университет стремится стать крупной технологической базой Узбекистана, предоставляя студентам глубокие инженерные знания, исследовательские возможности и интеграцию с мировой промышленностью, сотрудничая напрямую с такими объединениями, как АО «Узбекнефтегаз».', 'О нас', '/about', 'Наш университет стремится стать крупной технологической базой Узбекистана', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
INSERT INTO `home_section_translations` (`id`, `home_section_id`, `locale`, `eyebrow`, `title`, `subtitle`, `description`, `secondary_title`, `secondary_description`, `cta_label`, `cta_url`, `image_alt`, `created_at`, `updated_at`) VALUES ('24', '6', 'ar', 'الاندماج المؤسسي', 'هويتنا', NULL, 'تأسست BSTU من خلال دمج معهد بخارى للهندسة والتكنولوجيا ومعهد بخارى لإدارة الموارد الطبيعية (قرار الرئيس رقم PP-22)، لتجمع نخبة العلماء والباحثين ومرافق الحرم الجامعي في المنطقة.', NULL, 'تهدف جامعتنا إلى أن تصبح قاعدة تكنولوجية كبرى في أوزبكستان، من خلال تزويد الطلاب بخبرة هندسية عميقة وقدرات بحثية وتكامل صناعي عالمي، مع شراكات مباشرة مع مؤسسات كبرى مثل Uzbekneftegaz JSC.', 'من نحن', '/about', 'تهدف جامعتنا إلى أن تصبح قاعدة تكنولوجية كبرى في أوزبكستان', '2026-08-03 13:38:12', '2026-08-03 20:17:24');
