INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('1', '1', 'en', 'HEMIS Student Portal', 'Access your academic schedule, grades, course registration, and attendance records.', 'The dormitory is located just a 5-minute walk from academic buildings. Rooms are shared by 2 students. Security guards are active 24/7. Fees are paid per semester.', 'Login to HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('2', '1', 'uz', 'HEMIS talabalar portali', 'Dars jadvali, baholar, fanlarga ro‘yxatdan o‘tish va davomat ma’lumotlarini ko‘ring.', 'Talabalar turar joyi o‘quv binolaridan 5 daqiqalik masofada joylashgan. Xonalar 2 kishilik. Xavfsizlik xizmati 24/7 ishlaydi. To‘lovlar har semestrda amalga oshiriladi.', 'HEMISga kirish', '2026-07-21 05:44:39', '2026-07-21 06:27:37');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('3', '1', 'ru', 'Студенческий портал HEMIS', 'Просматривайте расписание, оценки, регистрацию на курсы и данные посещаемости.', 'Общежитие расположено всего в 5 минутах ходьбы от учебных корпусов. Комнаты рассчитаны на 2 студентов. Круглосуточная охрана. Оплата производится за семестр.', 'Войти в HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('4', '1', 'ar', 'بوابة الطالب HEMIS', 'يمكنك الوصول إلى جدولك الأكاديمي والدرجات وتسجيل المقررات وسجلات الحضور.', 'يقع السكن الجامعي على بعد 5 دقائق فقط سيرًا على الأقدام من المباني الأكاديمية. الغرف مشتركة لطالبين. الحراس الأمنيون متواجدون 24/7. تُدفع الرسوم لكل فصل دراسي.', 'تسجيل الدخول إلى HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('5', '2', 'en', 'Office of the Registrar', 'Manage your academic records, requests, official transcripts, and enrollment certificates.', 'Comprehensive laboratory research and academic training in food safety, industrial chemical engineering, and organic compounds.', 'Access Registrar Office', '2026-07-21 05:44:39', '2026-07-21 06:27:38');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('6', '2', 'uz', 'Registrator ofisi', 'Akademik yozuvlar, so‘rovlar, rasmiy transkriptlar va o‘qishga qabul sertifikatlarini boshqaring.', 'Oziq-ovqat xavfsizligi, sanoat kimyo muhandisligi va organik birikmalar bo‘yicha keng qamrovli laboratoriya tadqiqotlari va akademik tayyorgarlik.', 'Registrator ofisiga kirish', '2026-07-21 05:44:39', '2026-07-21 06:27:38');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('7', '2', 'ru', 'Офис регистратора', 'Управляйте академическими записями, запросами, официальными транскриптами и справками о зачислении.', 'Комплексные лабораторные исследования и академическая подготовка в области безопасности пищевых продуктов, промышленной химической инженерии и органических соединений.', 'офис регистратора', '2026-07-21 05:44:39', '2026-07-23 00:30:16');
INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('8', '2', 'ar', 'مكتب المسجل', 'إدارة السجلات الأكاديمية والطلبات والكشوف الرسمية وشهادات القيد.', 'أبحاث مخبرية شاملة وتدريب أكاديمي في مجال سلامة الأغذية، والهندسة الكيميائية الصناعية، والمركبات العضوية.', 'الدخول إلى مكتب المسجل', '2026-07-21 05:44:39', '2026-07-21 06:27:38');
