INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES ('11', '3', 'ru', 'Платформа дистанционного обучения', 'Подключайтесь к онлайн-лекциям, используйте электронные ресурсы и участвуйте в форумах.', 'Предоставление инженерного опыта и исследований в области добычи и переработки углеводородов, их транспортировки и разработки скважин.', 'Открыть Moodle', '2026-07-21 05:44:39', '2026-07-21 06:27:38');
